#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so the GC keeps the tracker alive; a raw pointer here was
	// collected mid-game and OnGoalScored dereferenced it (crash in Shipping).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker was held by a raw C++ pointer (UArenaScoreTracker* ScoreTracker) with no UPROPERTY in AArenaGameMode, so it was invisible to the Unreal garbage collector. A GC pass during play (log: 'LogGarbage: Collecting garbage: 412 objects purged' at 21:05:13) destroyed the tracker; the first goal at 21:05:27 called ScoreTracker->AddPoints() on the dangling pointer, causing EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18) from AArenaGameMode::OnGoalScored (ArenaGameMode.cpp:38). Fixed by making ScoreTracker a UPROPERTY TObjectPtr so the GC keeps it alive.",
  "no_colors_cause": "The arena palette asset /Game/Data/Palettes/DA_Primary is loaded at runtime with LoadObject in AArenaGameMode::BeginPlay, but the packaging settings (Config/DefaultGame.ini) had bCookAll=False and only /Game/Data/Effects in DirectoriesToAlwaysCook, so the /Game/Data/Palettes folder was never cooked into the pak. In the packaged build the load fails (log: 'LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary' and 'LogArena: Warning: Palette is null, using fallback gray'), the HUD falls back to gray and the arena renders without colors. It works in the editor because the asset exists on disk and is not cooked. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
